<span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">db.user</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">=</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">root</span></span>
